<template><div class="app-container"><el-alert title="风险中心默认只记录和人工处置，不会自动修改库存、佣金、资金或健康数据。" type="warning" :closable="false" style="margin-bottom:16px"/><div class="filter-container"><el-input v-model="query.riskType" placeholder="风险类型" style="width:200px"/><el-select v-model="query.riskLevel" clearable placeholder="等级"><el-option label="低" value="LOW"/><el-option label="中" value="MEDIUM"/><el-option label="高" value="HIGH"/></el-select><el-select v-model="query.status" clearable placeholder="状态"><el-option label="待处理" value="OPEN"/><el-option label="已处理" value="HANDLED"/><el-option label="已关闭" value="CLOSED"/></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table :data="list" border><el-table-column prop="eventNo" label="风险编号" min-width="180"/><el-table-column prop="riskType" label="类型"/><el-table-column prop="riskLevel" label="等级"/><el-table-column prop="summary" label="摘要" min-width="260"/><el-table-column prop="sourceNo" label="来源单号"/><el-table-column prop="status" label="状态"/><el-table-column prop="createTime" label="发现时间" min-width="160"/><el-table-column label="操作" width="140"><template slot-scope="{row}"><el-button v-if="row.status!=='CLOSED'" type="text" @click="handle(row,'HANDLE')">处理</el-button><el-button v-if="row.status!=='CLOSED'" type="text" @click="handle(row,'CLOSE')">关闭</el-button></template></el-table-column></el-table></div></template><script>import{getJkRiskEventList,handleJkRiskEvent}from'@/api/jkBusiness';export default{data(){return{query:{page:1,limit:20},list:[]}},created(){this.load()},methods:{load(){getJkRiskEventList(this.query).then(r=>this.list=(r&&r.list)||(r&&r.data&&r.data.list)||r.data||r||[])},handle(row,action){this.$prompt('处置说明','风险事件').then(({value})=>handleJkRiskEvent({id:row.id,action,remark:value}).then(()=>{this.$message.success('已更新');this.load()}))}}}</script>